def find_holes(grid):
    H, W = len(grid), len(grid[0])
    visited = set()
    holes = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 and (r,c) not in visited:
                # BFS from this cell
                queue = [(r, c)]
                component = set()
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        component.add((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 0:
                                if (nr, nc) not in component:
                                    queue.append((nr, nc))

                # Check if component is surrounded by 5s (a hole)
                touch_open = False
                for pos in component:
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = pos[0] + dr, pos[1] + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == 5:
                                pass  # touches wall
                            elif grid[nr][nc] != 0:  # not wall and not 0
                                touch_open = True

                if not touch_open and len(component) > 0:
                    holes.append(component)

    return holes

