def rotate_90cw(pattern):
    return {(y, -x) for x, y in pattern}

def normalize(pattern):
    max_x = max(x for x, y in pattern)
    max_y = max(y for x, y in pattern)
    return {(x - max_x, y - max_y) for x, y in pattern}

